let misses = 0;
const THRESHOLD = 3;

setInterval(async () => {
  const ok = await ping(primary, { timeoutMs: 1000 });
  misses = ok ? 0 : misses + 1;
  if (misses >= THRESHOLD) triggerFailover();
}, 2000);

// NAIVE: assumes the old primary is definitely dead. It might not be.
function triggerFailoverNaive() {
  replica.promote();
  router.pointWritesTo(replica);
}

async function triggerFailover() {
  const fenced = await fence(primary);       // revoke creds / cut route
  if (!fenced) throw new Error('cannot safely fail over: fence unconfirmed');

  await replica.promote();
  await router.pointWritesTo(replica);
}

async function renewLeaseLoop() {
  while (true) {
    const ok = await coordinator.renew(myLeaseId, { ttl: 5000 });
    if (!ok) { acceptingWrites = false; return; }   // can't renew: step down
    await sleep(2000);
  }
}

async function onRecoveredNodeRejoin(node) {
  const lastKnownOffset = await node.log.tail();
  await node.replicateFrom(currentPrimary, { fromOffset: lastKnownOffset });
  node.role = 'replica';   // never re-promotes itself
}
